// Turns the rendered document into compact text for the model. Every element the model can act on gets a
// reference (`data-aid`) and appears inline as `[ref kind: label]`, so labels are not repeated in a second list.
(prefix) => {
  const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "SVG", "HEAD"]);
  const BLOCK = new Set([
    "ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "CAPTION", "DD", "DETAILS", "DIALOG", "DIV", "DL", "DT",
    "FIELDSET", "FIGCAPTION", "FIGURE", "FOOTER", "FORM", "H1", "H2", "H3", "H4", "H5", "H6", "HEADER", "LI",
    "MAIN", "NAV", "OL", "P", "PRE", "SECTION", "SUMMARY", "TABLE", "TR", "UL",
  ]);
  const CLICKABLE =
    "a[href], button, summary, [role=button], [role=link], [role=tab], [role=menuitem], [role=option], " +
    "[role=checkbox], [role=radio], [role=switch]";
  const GENERIC_CLICKABLE = '[onclick], [tabindex]:not([tabindex="-1"])';

  const lines = [];
  let line = "";
  let count = 0;

  const flush = () => {
    const text = line.replace(/\s+/g, " ").trim();
    if (text) lines.push(text);
    line = "";
  };
  const clean = (value, limit) => (value || "").replace(/\s+/g, " ").trim().slice(0, limit);
  const mark = (el) => {
    const ref = prefix + count++;
    el.setAttribute("data-aid", ref);
    return ref;
  };
  const attrs = (el, names) =>
    names
      .map((name) => {
        const value = clean(el.getAttribute(name), 60);
        return value ? ` ${name}="${value}"` : "";
      })
      .join("");
  const disabled = (el) => (el.disabled || el.getAttribute("aria-disabled") === "true" ? " disabled" : "");
  const label = (el) =>
    clean(el.innerText, 120) ||
    clean(el.getAttribute("aria-label"), 120) ||
    clean(el.getAttribute("title"), 120) ||
    clean(el.value, 120) ||
    clean(el.querySelector("img[alt]")?.getAttribute("alt"), 120);
  const pointer = (el) => getComputedStyle(el).cursor === "pointer";
  const clearRefs = (root) => root.querySelectorAll("[data-aid]").forEach((el) => el.removeAttribute("data-aid"));

  const walk = (node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      line += node.textContent;
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const el = node;
    const tag = el.tagName.toUpperCase();
    if (SKIP.has(tag)) return;
    if (!el.checkVisibility({ visibilityProperty: true })) return;

    const block = BLOCK.has(tag);
    if (block) flush();

    if (tag === "BR") {
      flush();
      return;
    }
    if (tag === "IMG") {
      const alt = clean(el.getAttribute("alt"), 80);
      if (alt) line += ` [image: ${alt}] `;
      return;
    }
    if (tag === "IFRAME" || tag === "FRAME") {
      line += ` [embedded frame${attrs(el, ["title", "name"])}: its content is listed in its own section] `;
      return;
    }
    if (tag === "INPUT") {
      const type = (el.getAttribute("type") || "text").toLowerCase();
      if (type === "hidden") return;
      const ref = mark(el);
      if (["submit", "button", "reset", "image"].includes(type)) {
        line += ` [${ref} button: ${label(el)}${disabled(el)}] `;
        return;
      }
      let state = "";
      if (type === "checkbox" || type === "radio") state = el.checked ? " checked" : "";
      else if (type === "password") state = el.value ? ' value="(hidden)"' : "";
      else if (el.value) state = ` value="${clean(el.value, 80)}"`;
      line += ` [${ref} input:${type}${attrs(el, ["name", "placeholder", "aria-label"])}${state}${disabled(el)}] `;
      return;
    }
    if (tag === "TEXTAREA") {
      const value = el.value ? ` value="${clean(el.value, 200)}"` : "";
      line += ` [${mark(el)} textarea${attrs(el, ["name", "placeholder", "aria-label"])}${value}${disabled(el)}] `;
      return;
    }
    if (tag === "SELECT") {
      const options = [...el.options].slice(0, 40).map((option) => clean(option.text, 60));
      const selected = clean(el.selectedOptions[0]?.text, 60);
      line +=
        ` [${mark(el)} select${attrs(el, ["name", "aria-label"])} selected="${selected}"` +
        ` options="${options.join(" | ")}"${disabled(el)}] `;
      return;
    }
    if (el.matches(CLICKABLE)) {
      const kind = tag === "A" ? "link" : el.getAttribute("role") || tag.toLowerCase();
      line += ` [${mark(el)} ${kind}: ${label(el)}${disabled(el)}] `;
      if (block) flush();
      return;
    }
    // Containers that react to clicks keep their content readable, with a reference in front of it.
    const parent = el.parentElement;
    if (el.matches(GENERIC_CLICKABLE) || (pointer(el) && !(parent && pointer(parent)))) {
      line += ` [${mark(el)} clickable] `;
    }

    if (/^H[1-6]$/.test(tag)) line += "#".repeat(Number(tag[1])) + " ";
    if (tag === "LI") line += "- ";
    if (el.shadowRoot) {
      clearRefs(el.shadowRoot);
      for (const child of el.shadowRoot.childNodes) walk(child);
    }
    for (const child of el.childNodes) walk(child);
    if (tag === "TD" || tag === "TH") line += " | ";
    if (block) flush();
  };

  if (!document.body) return "";
  clearRefs(document);
  walk(document.body);
  flush();
  return lines.join("\n");
}

