    def page(self) -> Page:
        return self._pages[-1]

    def _adopt(self, page: Page) -> None:
        self._pages.append(page)
        page.on("popup", self._on_popup)
        page.on("dialog", lambda dialog: asyncio.ensure_future(self._on_dialog(dialog)))

    def _on_popup(self, page: Page) -> None:
        self._notices.append("The last action opened a new tab; you are now on it. Use close_tab to return.")
        self._adopt(page)

    async def _on_dialog(self, dialog: Dialog) -> None:
        self._notices.append(f"A {dialog.type} dialog appeared and was accepted: {dialog.message}")
        try:
            await dialog.accept()
        except Error:
            pass

    async def call(self, name: str, arguments: dict[str, Any]) -> str:
        """Run one tool call and return what the model reads next. Failures come back as text, not exceptions."""
        handler = getattr(self, f"_tool_{name}", None)
        if handler is None:
            return f"Unknown tool: {name}"
        try:
            return await handler(**arguments)
        except PlaywrightTimeout:
            return "The action timed out. The page may have changed; observe it again.\n\n" + await self._observe()
        except (Error, TypeError, ValueError) as error:
            return f"The action failed: {str(error).splitlines()[0]}\n\n" + await self._observe()

    # --- reading ---------------------------------------------------------------------------------------------

    async def _snapshot(self) -> None:
        self._frames = {}
        parts: list[str] = []
        for index, frame in enumerate(self.page.frames):
            prefix = f"f{index}"
            try:
                text = await frame.evaluate(SNAPSHOT_JS, f"{prefix}e")
            except Error:
                continue
            self._frames[prefix] = frame
            if frame is self.page.main_frame:
                parts.append(text)
            elif text:
                parts.append(f"--- embedded frame {prefix} ({frame.url}) ---\n{text}")
        self._text = "\n".join(parts)

    async def _observe(self, offset: int = 0) -> str:
        if offset == 0:
            await self._settle()
            await self._snapshot()
        header = ""
        if offset == 0:
            header = f"URL: {self.page.url}\nTitle: {await self.page.title()}\n"
            if len(self._pages) > 1:
                header += f"Open tabs: {len(self._pages)} (this is the newest)\n"
            if self._notices:
                header += "".join(f"Note: {notice}\n" for notice in self._notices)
                self._notices = []
            header += "\n"
        end = offset + PAGE_CHARS
        body = self._text[offset:end]
        if end < len(self._text):
            body += f"\n\n[The page continues: {len(self._text) - end} more characters. observe(offset={end})]"
        return header + (body or "(no visible text)")

    async def _settle(self) -> None:
        # A click may open a tab or start a navigation a moment later.
        await asyncio.sleep(0.25)
        try:
            await self.page.wait_for_load_state("domcontentloaded", timeout=LOAD_TIMEOUT_MS)
            await self.page.wait_for_load_state("networkidle", timeout=IDLE_TIMEOUT_MS)
        except (PlaywrightTimeout, Error):
            pass

    def _locate(self, ref: str) -> Locator:
        match = _REF.fullmatch(ref)
        frame = self._frames.get(match.group(1)) if match else None
        if frame is None:
            raise ValueError(f"No element {ref!r} in the latest page text")
        return frame.locator(f'[data-aid="{ref}"]')

    # --- tools -----------------------------------------------------------------------------------------------

    async def _tool_observe(self, offset: int = 0) -> str:
        return await self._observe(max(0, int(offset)))

    async def _tool_click(self, ref: str) -> str:
        target = self._locate(ref)
        try:
            await target.click(timeout=ACTION_TIMEOUT_MS)
        except PlaywrightTimeout:
            # Covered or animating elements: fire the click on the element itself.
            await target.dispatch_event("click", timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_type_text(self, ref: str, text: str, press_enter: bool = False) -> str:
        target = self._locate(ref)
        await target.fill(text, timeout=ACTION_TIMEOUT_MS)
        if press_enter:
            await target.press("Enter", timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_fill_credential(self, ref: str, field: str) -> str:
        if field not in self._credentials:
            raise ValueError(f"Unknown credential field {field!r}")
        await self._locate(ref).fill(self._credentials[field], timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_select_option(self, ref: str, option: str) -> str:
        target = self._locate(ref)
        try:
            await target.select_option(label=option, timeout=ACTION_TIMEOUT_MS)
        except (PlaywrightTimeout, Error):
            await target.select_option(value=option, timeout=ACTION_TIMEOUT_MS)
        return await self._observe()

    async def _tool_press_key(self, key: str) -> str:
        await self.page.keyboard.press(key)
        return await self._observe()

    async def _tool_open_url(self, url: str) -> str:
        if not url.startswith(("http://", "https://")):
            raise ValueError("open_url needs an absolute http(s) URL")
        await self.page.goto(url, wait_until="domcontentloaded", timeout=LOAD_TIMEOUT_MS * 2)
        return await self._observe()

    async def _tool_go_back(self) -> str:
        await self.page.go_back(wait_until="domcontentloaded", timeout=LOAD_TIMEOUT_MS)
        return await self._observe()

    async def _tool_close_tab(self) -> str:
        if len(self._pages) == 1:
            return "This is the only tab.\n\n" + await self._observe()
        await self._pages.pop().close()
        return await self._observe()


