// Renders one frame's DOM as compact text for the model. Interactive elements get a number in brackets,
// stamped on the element as data-aid so an action can find it again. Tables become " | " rows.
// Called with {prefix, start, full}; returns {text, next}.
({prefix, start, full}) => {
  let n = start;
  const lines = [];
  const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "SVG", "HEAD", "META", "LINK"]);
  const BLOCK = new Set(["DIV", "P", "SECTION", "ARTICLE", "MAIN", "HEADER", "FOOTER", "NAV", "ASIDE", "UL", "OL",
    "LI", "H1", "H2", "H3", "H4", "H5", "H6", "FORM", "FIELDSET", "LEGEND", "TR", "DL", "DT", "DD", "PRE", "BLOCKQUOTE",
    "DETAILS", "SUMMARY", "BR", "HR", "TABLE", "CAPTION", "FIGURE", "FIGCAPTION", "LABEL", "DIALOG"]);
  const clean = (s) => (s || "").replace(/[​-‏⁠﻿­]/g, "").replace(/\s+/g, " ").trim();
  // text the eye would get from hovering: a hidden tooltip, or a title/aria-label on a plain element
  const hint = (el) => {
    const parts = [];
    const own = clean(el.innerText || "") + " " + clean(el.textContent || "");
    for (const a of ["aria-label", "title", "data-tooltip", "datetime"]) {
      const v = clean(el.getAttribute(a));
      if (v && !own.includes(v) && !parts.includes(v)) parts.push(v);
    }
    const ref = referenced(el);
    if (ref) parts.push(ref);
    return parts.length ? ` (${parts.join("; ")})` : "";
  };
  // text of elements this one points to (tooltips, descriptions), even when they are hidden until hover
  const shownRefs = new Set();
  function referenced(el) {
    const out = [];
    for (const a of ["aria-describedby", "aria-labelledby", "aria-details"]) {
      for (const id of (el.getAttribute(a) || "").split(/\s+/).filter(Boolean)) {
        const target = document.getElementById(id);
        if (target && !target.contains(el) && !shownRefs.has(target)) {
          shownRefs.add(target);
          const v = clean(target.textContent);
          if (v) out.push(`tooltip: ${v}`);
        }
      }
    }
    return out.join("; ");
  }

  const hidden = (el) => {
    if (el.hidden || el.getAttribute("aria-hidden") === "true") return true;
    const cs = getComputedStyle(el);
    if (cs.display === "none") return true;
    if (cs.visibility === "hidden" && el.tagName !== "DETAILS") return true;
    return false;
  };
  const interactive = (el) => {
    const t = el.tagName;
    if (t === "A" && el.hasAttribute("href")) return true;
    if (["BUTTON", "SELECT", "TEXTAREA", "SUMMARY"].includes(t)) return true;
    if (t === "INPUT") return el.type !== "hidden";
    const role = el.getAttribute("role");
    if (["button", "link", "tab", "menuitem", "checkbox", "radio", "option", "switch"].includes(role)) return true;
    if (el.hasAttribute("onclick") || el.hasAttribute("data-action")) return true;
    return false;
  };
  const tag = (el) => {
    const id = `${prefix}${n++}`;
    el.setAttribute("data-aid", id);
    return id;
  };
  const describe = (el) => {
    const t = el.tagName;
    const id = tag(el);
    const extra = [];
    const title = el.getAttribute("title"), aria = el.getAttribute("aria-label");
    if (aria) extra.push(`aria="${clean(aria)}"`);
    if (title && title !== aria) extra.push(`title="${clean(title)}"`);
    if (el.disabled) extra.push("disabled");
    const ref = referenced(el);
    if (ref) extra.push(`(${ref})`);
    if (t === "A") {
      const href = el.getAttribute("href") || "";
      const dl = el.hasAttribute("download") ? " download" : "";
      return `[${id}] link "${clean(el.innerText)}"${extra.length ? " " + extra.join(" ") : ""} -> ${href.slice(0, 160)}${dl}`;
    }
    if (t === "INPUT") {
      const type = el.type || "text";
      const lbl = el.labels && el.labels[0] ? clean(el.labels[0].innerText) : "";
      if (type === "checkbox" || type === "radio")
        return `[${id}] ${type} name=${el.name} value="${el.value}" ${el.checked ? "CHECKED" : "unchecked"}${lbl ? ` label="${lbl}"` : ""} ${extra.join(" ")}`;
      if (type === "submit" || type === "button") return `[${id}] button "${el.value}" ${extra.join(" ")}`;
      if (type === "file") return `[${id}] file-input name=${el.name}`;
      const ph = el.placeholder ? ` placeholder="${el.placeholder}"` : "";
      return `[${id}] input(${type}) name=${el.name}${lbl ? ` label="${lbl}"` : ""}${ph} value="${el.value}"${el.readOnly ? " readonly" : ""} ${extra.join(" ")}`;
    }
    if (t === "TEXTAREA") return `[${id}] textarea name=${el.name} value="${clean(el.value).slice(0, 300)}"`;
    if (t === "SELECT") {
      const opts = [...el.options].map((o) => `${o.selected ? "*" : ""}${clean(o.text)}${o.value !== o.text ? `(${o.value})` : ""}`);
      return `[${id}] select name=${el.name} options: ${opts.join(" ; ").slice(0, 1500)}`;
    }
    if (t === "SUMMARY") return `[${id}] summary "${clean(el.innerText)}" (${el.parentElement.open ? "open" : "closed"})`;
    return `[${id}] ${t === "BUTTON" ? "button" : (el.getAttribute("role") || "clickable")} "${clean(el.innerText || el.value)}" ${extra.join(" ")}`;
  };

  // inline text of a node, with interactive descendants inlined as [id] markers
  const inline = (node, out) => {
    for (const c of node.childNodes) {
      if (c.nodeType === 3) { out.push(c.textContent); continue; }
      if (c.nodeType !== 1 || SKIP.has(c.tagName)) continue;
      if (hidden(c)) {
        if (c.getAttribute("role") === "tooltip") out.push(` (tooltip: ${clean(c.textContent)}) `);
        continue;
      }
      if (c.tagName === "IFRAME") { out.push(" [iframe] "); continue; }
      if (interactive(c)) { out.push(` ${describe(c)} `); continue; }
      inline(c, out);
      const h = hint(c);
      if (h) out.push(h);
    }
    return out;
  };

  const walk = (el, depth) => {
    if (el.nodeType === 3) { const s = clean(el.textContent); if (s) lines.push(s); return; }
    if (el.nodeType !== 1 || SKIP.has(el.tagName)) return;
    if (hidden(el)) {
      // tooltips and collapsed hints often carry data; keep their text, flagged
      const role = el.getAttribute("role");
      if (role === "tooltip" || el.tagName === "DETAILS") { const s = clean(el.textContent); if (s) lines.push(`(hidden ${role || "details"}: ${s.slice(0, 600)})`); }
      return;
    }
    const t = el.tagName;
    if (t === "IFRAME") { lines.push(`[iframe name="${el.name || ""}" src="${(el.getAttribute("src") || "").slice(0, 120)}" — its content follows as a separate frame]`); return; }
    if (t === "CANVAS") { const s = el.getAttribute("aria-label") || el.getAttribute("title") || ""; lines.push(`[canvas${s ? ": " + clean(s) : ""}]`); return; }
    if (t === "IMG") { const a = el.getAttribute("alt") || el.getAttribute("title"); if (a) lines.push(`[image: ${clean(a)}]`); return; }
    if (t === "TABLE") {
      const cap = el.querySelector(":scope > caption");
      if (cap) lines.push(`## ${clean(cap.innerText)}`);
      lines.push("<table>");
      for (const row of el.rows) {
        if (hidden(row)) continue;
        const cells = [...row.cells].map((c) => clean(inline(c, []).join(" ")));
        lines.push("| " + cells.join(" | ") + " |");
      }
      lines.push("</table>");
      return;
    }
    if (interactive(el)) {
      // a link/button that wraps block content: show its own text inline
      lines.push(describe(el));
      return;
    }
    if (t === "DT" && el.nextElementSibling && el.nextElementSibling.tagName === "DD") {
      lines.push(`${clean(inline(el, []).join(" "))}: ${clean(inline(el.nextElementSibling, []).join(" "))}`);
      el.nextElementSibling.setAttribute("data-agent-done", "1");
      return;
    }
    if (el.getAttribute("data-agent-done")) { el.removeAttribute("data-agent-done"); return; }
    const hasBlockChild = [...el.children].some((c) => BLOCK.has(c.tagName) || c.tagName === "TABLE" || c.tagName === "IFRAME" || c.tagName === "CANVAS");
    if (!hasBlockChild) {
      const s = clean(inline(el, []).join(" "));
      if (s) lines.push(/^H[1-6]$/.test(t) ? `${"#".repeat(+t[1])} ${s}` : s);
      return;
    }
    for (const c of el.childNodes) walk(c, depth + 1);
  };

  document.querySelectorAll("[data-aid]").forEach((e) => e.removeAttribute("data-aid"));
  if (document.body) walk(document.body, 0);
  // collapse duplicate consecutive lines
  const out = [];
  for (const l of lines) if (out[out.length - 1] !== l) out.push(l);
  return {text: out.join("\n"), next: n, title: document.title};
}

input.content:
"""Entering and signing the bid: a model works the submission website with a tool that fills many fields at once.

The model still chooses every field, value and button from the page it reads. Code only carries out a whole group
of those choices in one go: asking the model again after every single field makes a long form take longer than
the run lasts.
"""
import asyncio
import json
import time

from browser import Tab
from browsing import BrowsingAgent

SIGN_NOW_SECONDS = 150  # this long before the end the agent is told to stop filling and get the bid signed
STOP_SECONDS = 10
MODEL_CALL_SECONDS = 150
TOOL_SECONDS = 90
OPTION_WAIT_SECONDS = 6  # dependent dropdowns load their options after the one before them was chosen

SYSTEM = """You enter one finished bid into a website's submission form and get it signed and confirmed.
A bid that is entered but not signed and confirmed counts for nothing, so reaching the confirmation matters more
than any single field.

How the page view works: each page is shown as text; elements you can use carry a number in brackets, like [12] or
[f1.3] (inside a frame). Selects list their options, the chosen one marked with *.

How to work:
- Use fill_form for every group of fields you can see: give all of them in one call, in the order they appear on
  the page, and name the button that continues in click_after. Dropdowns that depend on each other (one choice
  changes the options of the next) work in one call too: list them in order, each with the option text you want.
- A fill_form result says for every field what was set or why it failed, then shows the page as it is now. Read
  it before you go on. After a failure, continue from that field with the numbers of the new page view.
- Enter the values of the answer exactly. Write numbers the way the form expects them (look at its examples,
  placeholders and error messages). Leave a field empty when the answer has no value for it.
- If the form has its own option to leave a position out and you were told to leave one out, use that option.
- Follow the brief's instructions for submitting. If a signing code is needed, get it where the brief says; that
  may be another of your websites.
- The websites are deliberately awkward: cookie notices, popups, error pages that work on a retry, sessions that
  expire and return you to the sign-in page (use the login tool). Never accept surveys or unrelated offers.
- Do not change or recompute any value of the answer.
- When the site confirms the bid, call finish with the receipt text exactly as shown. If you cannot get there,
  call finish and say exactly what is entered, what is missing and what stopped you.
"""

SIGN_NOW = ("Time is nearly over. Stop filling optional fields: go on to signing and confirming the bid now, with "
            "what is entered. If positions are still empty and the form can leave a position out, use that.")

IDENTITY_JS = """el => ({
  tag: el.tagName, type: (el.type || "").toLowerCase(), name: el.name || "", id: el.id || "",
  label: ((el.labels && el.labels[0] ? el.labels[0].innerText : "") || el.getAttribute("aria-label") || el.name || "")
    .replace(/\\s+/g, " ").trim().slice(0, 60),
})"""

# Finds the option the model named: exact text or value first, then a text that starts with it or contains it,
# as long as only one option does.
OPTION_JS = """(el, wanted) => {
  const norm = (s) => (s || "").replace(/\\s+/g, " ").trim().toLowerCase();
  const w = norm(wanted);
  const options = [...el.options].filter((o) => !o.disabled);
  const only = (test) => { const hits = options.filter(test); return hits.length === 1 ? hits[0] : null; };
  const hit = options.find((o) => norm(o.text) === w || norm(o.value) === w)
    || only((o) => norm(o.text).startsWith(w)) || only((o) => norm(o.text).includes(w));
  return {
    disabled: el.disabled,
    match: hit ? {value: hit.value, text: hit.text.replace(/\\s+/g, " ").trim()} : null,
    options: options.map((o) => o.text.replace(/\\s+/g, " ").trim()).filter(Boolean).slice(0, 60),
  };
}"""


def tool_schemas(sites: list[str]) -> list[dict]:
    site = {"type": "string", "enum": sites, "description": "which website"}
    element = {"type": "string", "description": "element number from the latest page view of that website"}

    def tool(name: str, description: str, properties: dict, required: list[str]) -> dict:
        return {"type": "function", "function": {"name": name, "description": description, "parameters": {
            "type": "object", "properties": properties, "required": required}}}

    return [
        tool("look", "Show the current page of a website again.", {"site": site}, ["site"]),
        tool("goto", "Open a URL (absolute, or a path on the site).", {"site": site, "url": {"type": "string"}},
             ["site", "url"]),
        tool("click", "Click one element.", {"site": site, "element": element}, ["site", "element"]),
        tool("fill_form",
             "Set several fields in one go, in the order given, then optionally click a button. For a text field the "
             "value is typed; for a select it is the option's text; for a checkbox or radio button it is true or "
             "false. Stops at the first field that fails and reports every field.",
             {"site": site,
              "fields": {"type": "array", "items": {"type": "object", "properties": {
                  "element": element, "value": {"type": "string"}}, "required": ["element", "value"]}},
              "click_after": {"type": "string", "description": "element number of the button to click once every "
                                                                "field is set, e.g. the one that continues"}},
             ["site", "fields"]),
        tool("read_more", "Continue reading a long page view from a character offset.",
             {"site": site, "offset": {"type": "integer"}}, ["site", "offset"]),
        tool("login", "Sign in to a website with its own login on the current sign-in form.", {"site": site},
             ["site"]),
        tool("finish", "End with your report: the receipt exactly as shown, or what is entered and what stopped you.",
             {"report": {"type": "string"}}, ["report"]),
    ]


class SubmissionAgent:
    def __init__(self, model, tabs: dict[str, Tab], credentials: dict[str, dict], task: str, context: str,
                 deadline: float, max_steps: int = 80, log=print):
        self.model, self.tabs, self.task, self.context = model, tabs, task, context
        self.deadline, self.max_steps, self.log = deadline, max_steps, log
        # the sign-in helper of the browsing sub-agent, so there is one place that knows how to sign in
        self._browsing = BrowsingAgent(model, tabs, credentials, "", "", name="submit", deadline=deadline, log=log)

    async def run(self) -> str:
        views = [f"# Current page of {site}\n{await tab.observe()}" for site, tab in self.tabs.items()]
        messages = [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": f"{self.context}\n\n# Your websites\n" + "\n".join(f"- {s}" for s in self.tabs)
             + f"\n\n# Your task\n{self.task}\n\n" + "\n\n".join(views)},
        ]
        tools = tool_schemas(list(self.tabs))
        told_to_sign = False
        for step in range(self.max_steps):
            remaining = self.deadline - time.time()
            if remaining < STOP_SECONDS:
                break
            if remaining < SIGN_NOW_SECONDS and not told_to_sign:
                messages.append({"role": "user", "content": SIGN_NOW})
                told_to_sign = True
            try:
                message = await asyncio.wait_for(self.model.chat(messages, tools, temperature=0.2),
                                                 timeout=min(remaining, MODEL_CALL_SECONDS))
            except TimeoutError:
                self.log("[submit] a model call took too long; asking again")
                continue
            calls = message.tool_calls or []
            entry = {"role": "assistant", "content": message.content or ""}
            if calls:
                entry["tool_calls"] = [{"id": c.id, "type": "function", "function": {
                    "name": c.function.name, "arguments": c.function.arguments}} for c in calls]
            messages.append(entry)
            if not calls:
                messages.append({"role": "user", "content": "Use a tool: continue the submission, or call finish."})
                continue
            for call in calls:
                try:
                    args = json.loads(call.function.arguments or "{}")
                except ValueError:
                    args = {}
                if call.function.name == "finish":
                    self.log(f"[submit] finished after {step + 1} steps")
                    return "REPORT:\n" + str(args.get("report", ""))
                self.log(f"[submit] {call.function.name} {_summary(args)}")
                try:
                    result = await asyncio.wait_for(self._run_tool(call.function.name, args), timeout=TOOL_SECONDS)
                except TimeoutError:
                    result = "Error: the action did not finish in time. Look at the page again."
                except Exception as error:  # noqa: BLE001 - the model reads the failure and decides what to do
                    result = f"Error: {str(error).splitlines()[0][:400]}"
