        print("--- case 2: an option that does not exist")
        print(out.split("# The page now")[0].strip())
        print("page says:", repr(await page.inner_text("#result")), "| amount field:", repr(await page.input_value("[name=c]")))

        out = await fill_form(tab, [{"element": "999", "value": "x"}])
        print("--- case 3: a number that is not on the page")
        print(out.split("# The page now")[0].strip())
        await browser.close()

asyncio.run(main())
PYEOF

