  el.innerHTML = html;
  const q = n => el.querySelector(`[name=${n}]`);
  q("type").onchange = e => { s = {type: e.target.value}; setTimeout(render, 400); };
  if (q("colour")) q("colour").onchange = e => { s.colour = e.target.value; setTimeout(render, 400); };
  if (q("amount")) { q("amount").oninput = e => s.amount = e.target.value; q("price").oninput = e => s.price = e.target.value; q("ok").onchange = e => s.ok = e.target.checked;
    document.getElementById("go").onclick = () => { saved.push({position, ...s}); position += 1; s = {}; render(); }; }
}
render();
</script></body></html>
