import asyncio, re, sys, time
from playwright.async_api import async_playwright
from browser import Tab
from submission import fill_form
async def main():
    async with async_playwright() as pw:
        browser = await pw.chromium.launch(); page = await browser.new_page()
        await page.goto("file://" + sys.argv[1]); tab = Tab("form", page, log=lambda *a: None)
        view = await tab.observe()
        print("fields visible at the start:", re.findall(r"\[\d+\] (?:select|input\(\w+\)|checkbox) name=(\w+)", view))
        first = re.search(r"\[(\d+)\] select name=type", view).group(1)
        t = time.time()
        out = await fill_form(tab, [{"element": first, "value": "Alpha"}, {"label": "Colour", "value": "red 10"},
                                    {"label": "Amount", "value": "12"}, {"label": "Unit price", "value": "3,50"},
                                    {"label": "Confirmed", "value": "true"}], "Continue")
        print(f"--- position 1 in one call ({time.time()-t:.1f} s): number for the first field, labels for the ones that appear later")
        print(out.split("# The page now")[0].strip())
        t = time.time()
        out = await fill_form(tab, [{"label": "Type", "value": "Beta"}, {"label": "Colour", "value": "Yellow"},
                                    {"label": "amount", "value": "7"}, {"label": "price", "value": "1,00"}], "Continue")
        print(f"--- position 2 in one call ({time.time()-t:.1f} s): labels only")
        print(out.split("# The page now")[0].strip())
        print("page says:", await page.inner_text("#result"))
        await page.reload(); await tab.observe()
        out = await fill_form(tab, [{"label": "Type", "value": "Alpha"}, {"label": "Shade", "value": "x"}, {"label": "Amount", "value": "1"}], "Continue")
        print("--- a label that does not exist"); print(out.split("# The page now")[0].strip())
        await browser.close()
asyncio.run(main())
